#!/usr/bin/env bash
# Builds CLAUDE.md and CLAUDE.inline.md from core/, interactive/ and autonomous/.
#   ./build.sh          rewrite the generated files
#   ./build.sh --check  exit 1 if any generated file is out of date
set -euo pipefail
cd "$(dirname "$0")"

REPO_HOME='~/Development/agent-rules'
NOTE='<!-- GENERATED by build.sh. Edit files in core/, interactive/ or autonomous/, then run ./build.sh. -->'
INLINE_NOTE='<!-- Generated from github.com/wz185/agent-rules. Do not edit here. -->'
OUTPUTS=(CLAUDE.md CLAUDE.inline.md)

# Local profile: imports, so rule edits apply without a rebuild.
local_md() {
  printf '# Global rules\n\n'
  for f in core/*.md interactive/*.md autonomous/*.md; do
    printf '@%s/%s\n' "$REPO_HOME" "$f"
  done
  printf '\n---\n%s\n%s\n' "$NOTE" \
    '<!-- Budget: this file + all imports must stay under 150 lines total. Situational rules → a skill. -->'
}

# Cloud profiles: rule text inlined, headings demoted one level.
inline_md() {
  local title=$1; shift
  printf '# %s\n\n%s\n' "$title" "$INLINE_NOTE"
  for f in "$@"; do
    printf '\n'
    sed -E 's/^(#+) /#\1 /' "$f"
  done
}

build() {
  local out=$1
  local_md > "$out/CLAUDE.md"
  inline_md 'Personal Claude Code rules (inlined)' core/*.md interactive/*.md > "$out/CLAUDE.inline.md"
}

if [[ ${1:-} == --check ]]; then
  tmp=$(mktemp -d); trap 'rm -rf "$tmp"' EXIT
  build "$tmp"
  stale=0
  for f in "${OUTPUTS[@]}"; do
    cmp -s "$tmp/$f" "$f" || { echo "Out of date: $f. Run ./build.sh" >&2; stale=1; }
  done
  exit $stale
fi
build .
